/-- The observed group mean under its assigned arm. -/
noncomputable def obsGroupMean {n M G G1 : ℕ} (Y : PotentialOutcome n M)
    (w : PartitionTuple n M G × TreatmentSpace G G1) (g : Fin G) : ℝ :=
  if g ∈ w.2.1 then armTable n M Y true (w.1.1 g)
  else armTable n M Y false (w.1.1 g)

/-- The canonical degree-`k` Johnson harmonic space: the degree-at-most-`k`
space orthogonal to all lower-degree inclusion monomials. -/
def johnsonHarmonicSpace (n M : ℕ) (hM : M ≤ n) (k : Fin (M + 1)) :
    Set (Omega n M → ℝ) :=
  {f | WithLp.toLp 2 f ∈ johnsonHarmonic n M k.1}

aux_CountAlignment.statement:
/-- An array's grouped-unit counts agree row-by-row with the birthday benchmark. -/
def CountAlignment {groupSize : ℕ} (A : ScheduleArray groupSize) (M : ℕ) : Prop :=
  ∀ r, A.grouped r = birthdayGroupedUnits M (A.popSize r)

